// src/bitable/table-client.ts
class BitableClient {
  constructor(private client: any) {}

  // Query table records (with filtering and pagination)
  async listRecords(
    appToken: string,
    tableId: string,
    options?: {
      filter?: string;
      sort?: string[];
      pageSize?: number;
      pageToken?: string;
    }
  ) {
    const resp = await this.client.bitable.appTableRecord.list({
      path: { app_token: appToken, table_id: tableId },
      params: {
        filter: options?.filter,
        sort: options?.sort ? JSON.stringify(options.sort) : undefined,
        page_size: options?.pageSize || 100,
        page_token: options?.pageToken,
      },
    });

    if (resp.code !== 0) {
      throw new Error(`Failed to query records: ${resp.msg}`);
    }
    return resp.data;
  }

  // Batch create records
  async batchCreateRecords(
    appToken: string,
    tableId: string,
    records: Array<{ fields: Record<string, any> }>
  ) {
    const resp = await this.client.bitable.appTableRecord.batchCreate({
      path: { app_token: appToken, table_id: tableId },
      data: { records },
    });

    if (resp.code !== 0) {
      throw new Error(`Failed to batch create records: ${resp.msg}`);
    }
    return resp.data;
  }

  // Update a single record
  async updateRecord(
    appToken: string,
    tableId: string,
    recordId: string,
    fields: Record<string, any>
  ) {
    const resp = await this.client.bitable.appTableRecord.update({
      path: {
        app_token: appToken,
        table_id: tableId,
        record_id: recordId,
      },
      data: { fields },
    });

    if (resp.code !== 0) {
      throw new Error(`Failed to update record: ${resp.msg}`);
    }
    return resp.data;
  }
}

// Example: Sync external order data to a Bitable spreadsheet
async function syncOrdersToBitable(orders: any[]) {
  const bitable = new BitableClient(client);
  const appToken = process.env.BITABLE_APP_TOKEN!;
  const tableId = process.env.BITABLE_TABLE_ID!;

  const records = orders.map((order) => ({
    fields: {
      'Order ID': order.orderId,
      'Customer Name': order.customerName,
      'Order Amount': order.amount,
      'Status': order.status,
      'Created At': order.createdAt,
    },
  }));

  // Maximum 500 records per batch
  for (let i = 0; i < records.length; i += 500) {
    const batch = records.slice(i, i + 500);
    await bitable.batchCreateRecords(appToken, tableId, batch);
  }
}
